package site

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"go/format"
	"net/http"
	"net/url"

	"github.com/Tend-Stack/TendUI/v2026/components"
)

const appearanceCookie = "tendui_appearance"

func appearance(r *http.Request) components.Appearance {
	a := components.Appearance{}
	if cookie, err := r.Cookie(appearanceCookie); err == nil && len(cookie.Value) < 2048 {
		if b, err := base64.RawURLEncoding.DecodeString(cookie.Value); err == nil {
			var saved components.Appearance
			if json.Unmarshal(b, &saved) == nil {
				a = saved
			}
		}
	}
	return appearanceFromValues(a, r.URL.Query())
}

func appearanceFromValues(a components.Appearance, q url.Values) components.Appearance {
	if q.Has("preset") {
		a.Preset = components.Preset(q.Get("preset"))
	}
	if q.Has("density") {
		a.Density = components.Density(q.Get("density"))
	}
	if q.Has("corners") {
		a.Corners = components.Corners(q.Get("corners"))
	}
	if q.Has("typography") {
		a.Typography = components.Typography(q.Get("typography"))
	}
	if q.Has("text_size") {
		a.TextSize = components.TextSize(q.Get("text_size"))
	}
	if q.Has("width") {
		a.Width = components.ContentWidth(q.Get("width"))
	}
	if q.Has("elevation") {
		a.Elevation = components.Elevation(q.Get("elevation"))
	}
	if q.Has("motion") {
		a.Motion = components.MotionPreference(q.Get("motion"))
	}
	return a.Normalize()
}

func appearanceValues(a components.Appearance) url.Values {
	a = a.Normalize()
	return url.Values{
		"preset": {string(a.Preset)}, "density": {string(a.Density)}, "corners": {string(a.Corners)},
		"typography": {string(a.Typography)}, "text_size": {string(a.TextSize)},
		"width": {string(a.Width)}, "elevation": {string(a.Elevation)}, "motion": {string(a.Motion)},
	}
}

func themeName(t components.Theme) string {
	if t == components.ThemeSystem {
		return "system"
	}
	return string(t)
}

func saveAppearance(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 8<<10)
	if err := r.ParseForm(); err != nil {
		http.Error(w, "Invalid settings form (maximum 8 KB)", http.StatusBadRequest)
		return
	}
	a := appearanceFromValues(components.Appearance{}, r.PostForm)
	encoded, _ := json.Marshal(a)
	mode := choice(r.PostForm.Get("theme"), "light", "light", "dark", "system")
	maxAge := 365 * 24 * 60 * 60
	if r.PostForm.Get("action") == "reset" {
		maxAge = -1
	}
	for name, value := range map[string]string{appearanceCookie: base64.RawURLEncoding.EncodeToString(encoded), "tendui_theme": mode} {
		http.SetCookie(w, &http.Cookie{Name: name, Value: value, Path: "/", MaxAge: maxAge, HttpOnly: true, SameSite: http.SameSiteStrictMode, Secure: r.TLS != nil})
	}
	w.Header().Set("Cache-Control", "no-store")
	http.Redirect(w, r, "/settings?saved=1", http.StatusSeeOther)
}

func appearanceExportURL(a components.Appearance, mode, extension string) string {
	q := appearanceValues(a)
	q.Set("theme", mode)
	return "/appearance." + extension + "?" + q.Encode()
}

func exportAppearance(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		w.Header().Set("Allow", "GET, HEAD")
		http.Error(w, "method not allowed", 405)
		return
	}
	a := appearance(r)
	data := []byte(a.CSS())
	w.Header().Set("Content-Type", "text/css; charset=utf-8")
	filename := "tendui-appearance.css"
	if r.URL.Path == "/appearance.go" {
		source := fmt.Sprintf("// Generated by the TendUI appearance demo.\npackage theme\n\nimport \"github.com/Tend-Stack/TendUI/v2026/components\"\n\nvar Appearance = components.Appearance{Preset: %q, Density: %q, Corners: %q, Typography: %q, TextSize: %q, Width: %q, Elevation: %q, Motion: %q}\n\nvar Mode = components.Theme(%q)\n", a.Preset, a.Density, a.Corners, a.Typography, a.TextSize, a.Width, a.Elevation, a.Motion, theme(r))
		var err error
		data, err = format.Source([]byte(source))
		if err != nil {
			http.Error(w, "Unable to export settings", 500)
			return
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		filename = "tendui_appearance.go"
	}
	w.Header().Set("Content-Disposition", `attachment; filename="`+filename+`"`)
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	if r.Method != http.MethodHead {
		_, _ = w.Write(data)
	}
}

type appearanceField struct {
	Name, Label, Value string
	Options            []components.Option
}

func appearanceFields(a components.Appearance) []appearanceField {
	a = a.Normalize()
	return []appearanceField{
		{"preset", "Color preset", string(a.Preset), []components.Option{{Label: "Indigo", Value: "indigo"}, {Label: "Neutral", Value: "neutral"}, {Label: "Forest", Value: "forest"}, {Label: "Rose", Value: "rose"}}},
		{"density", "Spacing", string(a.Density), []components.Option{{Label: "Comfortable", Value: "comfortable"}, {Label: "Compact", Value: "compact"}}},
		{"corners", "Corners", string(a.Corners), []components.Option{{Label: "Rounded", Value: "rounded"}, {Label: "Nearly square", Value: "square"}, {Label: "Soft", Value: "soft"}}},
		{"typography", "Font family", string(a.Typography), []components.Option{{Label: "System sans", Value: "sans"}, {Label: "System serif", Value: "serif"}, {Label: "System monospace", Value: "mono"}}},
		{"text_size", "Text size", string(a.TextSize), []components.Option{{Label: "Standard", Value: "standard"}, {Label: "Large", Value: "large"}}},
		{"width", "Page width", string(a.Width), []components.Option{{Label: "Standard", Value: "standard"}, {Label: "Narrow", Value: "narrow"}, {Label: "Wide", Value: "wide"}}},
		{"motion", "Motion", string(a.Motion), []components.Option{{Label: "Follow system preference", Value: "system"}, {Label: "Off", Value: "off"}}},
		{"elevation", "Surface shadows", string(a.Elevation), []components.Option{{Label: "Flat", Value: "flat"}, {Label: "Subtle", Value: "subtle"}, {Label: "Raised", Value: "raised"}, {Label: "Floating", Value: "floating"}}},
	}
}
